<template>
  <div class="order-center">
    <sf-segmented-control class="order-center__tabs" appearance="line" :items="tabs" :value="tab" label="Order type" @input="$emit('tab',$event)"/>
    <section id="order-history-panel" role="tabpanel" :aria-label="selectedLabel" class="order-center__list" :data-order-type="tab">
      <sf-feedback v-if="!records.length" tone="empty" :title="emptyTitle"/>
      <article v-for="order in records" :key="order.id" class="order-record sf-card" :data-order-id="order.id" :data-order-unit="order.unit">
        <header><span>{{ date(order.date) }}</span><span class="order-record__status" :class="{'is-pending':['Scheduled','Processing'].includes(order.status)}">{{ order.status }}</span></header>
        <div class="order-record__item"><div class="order-record__art" :class="'order-record__art--'+order.icon"><img v-if="order.image" :src="order.image" alt=""/><sf-icon v-else :name="order.icon" :size="27"/></div><div><h3>{{ order.title }}</h3><p>{{ order.subtitle }}</p></div><small v-if="order.quantity">×{{ order.quantity }}</small></div>
        <footer><strong><sf-icon v-if="order.unit==='Points'" name="coins" :size="15"/>{{ amount(order) }}<small v-if="!['money','legacy'].includes(order.unit)">{{ order.unit }}</small></strong><button type="button" @click="$emit('detail',order)">View Detail<sf-icon name="chevron-right" :size="12"/></button></footer>
      </article>
    </section>
  </div>
</template>
<script>
import {SfIcon,SfSegmentedControl,SfFeedback} from '@/design-system'
import {orderTypes,orderRecords,reviewOrderRecords} from './order-center.cjs'
export default {
  components:{SfIcon,SfSegmentedControl,SfFeedback},props:{data:Object,tab:String,mode:String,locale:String},
  computed:{tabs(){return orderTypes.map(item=>({...item,panelId:'order-history-panel'}))},selectedLabel(){return orderTypes.find(item=>item.value===this.tab)?.label},records(){return this.mode==='empty'?[]:this.mode==='examples'?reviewOrderRecords(this.tab):orderRecords(this.data,this.tab)},emptyTitle(){return {'subscription':'No purchases yet','points-exchange':'No points exchanges yet','star-content':'No content unlocks yet'}[this.tab]}},
  methods:{date(value){return new Intl.DateTimeFormat(this.locale||'en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date(value))},amount(order){if(order.unit==='legacy')return 'Legacy unlock';return order.unit==='money'?new Intl.NumberFormat(this.locale||'en-US',{style:'currency',currency:order.currency}).format(order.amount/100):new Intl.NumberFormat(this.locale||'en-US').format(order.amount)}}
}
</script>
<style scoped>
.order-center{color:var(--sf-text);min-width:0}.order-center__tabs{position:sticky;top:-1px;z-index:2;margin:-4px -16px 16px;padding:0 16px;background:var(--sf-page);gap:0;justify-content:space-between;border-radius:0}.order-center__tabs::v-deep button{font-size:12px;line-height:18px;min-height:48px;padding:8px 0;flex:0 1 auto;white-space:nowrap;letter-spacing:-.15px}.order-center__tabs::v-deep button[aria-selected=true]::after{left:0;right:auto;width:22px;height:3px;border-radius:3px}.order-center__list{display:grid;gap:14px;min-width:0;outline:none}.order-record{padding:14px;border-radius:16px;min-width:0}.order-record>header{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:11px;line-height:17px;color:var(--sf-text-secondary);padding-bottom:12px;border-bottom:1px solid var(--sf-content-edge)}.order-record__status{color:#3d7857;font-weight:500}.order-record__status.is-pending{color:#9b742a}.order-record__item{display:flex;align-items:center;gap:12px;min-width:0;padding:16px 0}.order-record__art{display:grid;place-items:center;width:64px;height:64px;flex:none;background:#eef2fa;color:#5b6b92;border-radius:12px;overflow:hidden}.order-record__art--membership{background:linear-gradient(135deg,#f8eddb,#f3d7a3);color:#8e6229}.order-record__art--ticket{background:#fff0ee;color:#e16f62}.order-record__art>img{width:100%;height:100%;object-fit:cover}.order-record__item>div:nth-child(2){min-width:0;flex:1}.order-record__item h3{font-size:15px;line-height:22px;font-weight:600;margin:0;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}.order-record__item p{font-size:11px;line-height:17px;color:var(--sf-text-secondary);margin:5px 0 0}.order-record__item>small{align-self:flex-start;padding-top:4px;color:var(--sf-text-secondary);font-size:12px}.order-record>footer{display:flex;align-items:center;justify-content:space-between;gap:8px}.order-record>footer>strong{display:flex;align-items:center;gap:4px;flex-wrap:wrap;font-size:16px;line-height:24px;font-weight:600;min-width:0}.order-record>footer>strong small{font-size:10px;line-height:16px;font-weight:400;color:var(--sf-text-secondary)}.order-record[data-order-unit=Points]>footer>strong{color:var(--sf-action)}.order-record>footer>button{display:flex;align-items:center;justify-content:flex-end;gap:4px;border:0;background:transparent;color:var(--sf-text-secondary);min-height:44px;padding:8px 0 8px 10px;font:400 11px/18px var(--sf-font-family);cursor:pointer;white-space:nowrap}.order-center__list>.sf-feedback{margin-top:85px}

.order-center .order-center__tabs{background:transparent;border:0;box-shadow:none;backdrop-filter:none;border-radius:0;padding:0 16px;overflow:visible}.order-center .order-center__tabs::v-deep button{position:relative;border:0;border-radius:0;background:transparent;box-shadow:none;color:var(--sf-text-secondary)}.order-center .order-center__tabs::v-deep button[aria-selected=true]{background:transparent;box-shadow:none;color:var(--sf-action)}.order-center .order-center__tabs::v-deep button[aria-selected=true]::after{content:'';position:absolute;bottom:3px;left:0;width:22px;height:3px;border-radius:3px;background:currentColor}
</style>
